  "nav.radius": "Accès réseau (RADIUS)",
  "radius.tab_service": "Service",
  "radius.tab_clients": "Clients (équipements)",
  "radius.intro": "Serveur RADIUS de ce nœud (FreeRADIUS) pour l'authentification 802.1X du Wi-Fi et des VPN. Il vérifie le certificat EAP-TLS du poste ou de l'utilisateur, interroge l'annuaire Active Directory (compte, état, groupes imbriqués) et applique vos règles d'accès, dans l'ordre : la première qui correspond décide, sans règle l'accès est refusé.",
  "radius.absent_title": "Paquet freeradius absent",
  "radius.absent_body": "Le service RADIUS n'est pas installé sur ce nœud. Il est installé par l'ISO DDI-Buntu (installation ou mode Mise à jour) ; la mise à jour en ligne n'installe pas de paquet.",
  "radius.state": "État du service",
  "radius.running": "En marche",
  "radius.cl_active": "Actif sur ce nœud",
  "radius.cl_active_body": "RADIUS tourne ici, sur le leader du cluster. Les équipements (bornes, passerelles VPN) doivent viser l'adresse virtuelle : elle suit le leader.",
  "radius.cl_standby": "En veille",
  "radius.cl_standby_body": "RADIUS est arrêté sur ce nœud (secondaire) : il tourne sur le leader ({leader}) et reprend ici tout seul si ce nœud devient leader. Le déploiement se fait depuis le nœud actif.",
  "radius.cl_vip": "Adresse virtuelle du cluster : {vip}",
  "radius.cl_follow": "Dernière reprise automatique après une bascule : {date} — {state}",
  "radius.cl_follow_run": "en cours",
  "radius.cl_follow_ok": "réussie",
  "radius.stopped": "Arrêté",
  "radius.never": "Pas encore déployé",
  "radius.never_hint": "Déclarez au moins un client dans l'onglet Clients, puis déployez le service.",
  "radius.package": "Paquet",
  "radius.installed": "Installé",
  "radius.absent": "Absent",
  "radius.version": "Version",
  "radius.boot": "Démarrage automatique",
  "radius.clients_active": "Équipements déployés",
  "radius.ports": "Ports UDP",
  "radius.read_at": "État relevé le",
  "radius.node_note": "Ces informations concernent ce nœud uniquement.",
  "radius.last": "Dernière opération :",
  "radius.pending": "Une demande est en cours de traitement…",
  "radius.sent": "Demande envoyée",
  "radius.deploy": "Déployer",
  "radius.deploy_title": "Déployer le service RADIUS ?",
  "radius.deploy_body": "Les clients actifs sont écrits, la configuration est contrôlée, puis le service est (re)démarré : les authentifications en cours sont brièvement interrompues. Le pare-feu s'ouvre aux seuls réseaux de ces clients (UDP 1812 et 1813). En cas d'échec, la configuration précédente est restaurée.",
  "radius.stop": "Arrêter",
  "radius.stop_title": "Arrêter le service RADIUS ?",
  "radius.stop_body": "Tant que le service est arrêté, les équipements ne peuvent plus authentifier leurs utilisateurs (Wi-Fi, VPN). Le pare-feu referme les ports 1812 et 1813.",
  "radius.test": "Tester une requête",
  "radius.test_hint": "Envoie un Access-Request signé depuis cette console, comme le ferait un équipement. « Refus » est la bonne réponse : le test n'utilise pas EAP-TLS, donc aucune règle ne peut l'accepter. Pour vérifier une règle, utilisez la simulation (onglet Règles d'accès).",
  "radius.test_reject": "Le service répond : Access-Reject authentique en {ms} ms. C'est la réponse attendue (aucune règle d'accès : tout est refusé par défaut).",
  "radius.test_accept": "Le service répond : Access-Accept en {ms} ms.",
  "radius.test_challenge": "Le service répond : Access-Challenge en {ms} ms.",
  "radius.test_timeout": "Aucune réponse : le service est arrêté ou mal configuré, ou le pare-feu bloque la requête.",
  "radius.test_bad_reply": "Réponse invalide : sa signature ne correspond pas au secret attendu.",
  "radius.test_socket": "Erreur réseau locale pendant le test.",
  "radius.cl_help": "Un client est un équipement qui interroge RADIUS : contrôleur Wi-Fi, passerelle VPN, commutateur. Le secret partagé se saisit sur l'équipement ; il est chiffré ici et n'est montré qu'une seule fois.",
  "radius.cl_add": "Ajouter un client",
  "radius.cl_name_hint": "Minuscules, chiffres et tirets ; commence par une lettre.",
  "radius.cl_address": "Adresse ou réseau",
  "radius.cl_address_hint": "IPv4 ou IPv6, avec ou sans masque. Réseau limité à /16 (IPv4) ou /48 (IPv6) au plus large.",
  "radius.cl_usage": "Usage",
  "radius.u.wifi": "Wi-Fi 802.1X",
  "radius.u.vpn": "VPN",
  "radius.u.switch": "Commutateur (802.1X filaire)",
  "radius.u.other": "Autre",
  "radius.cl_secret": "Secret partagé",
  "radius.cl_secret_hint": "Laissez vide pour en générer un à la création (32 caractères), ou pour conserver l'actuel à la modification. 16 à 128 caractères : lettres, chiffres et . _ ~ + = : @ , ; ( ) ! * -",
  "radius.cl_apply_note": "Les changements de clients ne sont pris en compte qu'au prochain déploiement du service (onglet Service).",
  "radius.regen": "Régénérer le secret",
  "radius.regen_title": "Régénérer le secret ?",
  "radius.regen_body": "L'ancien secret de « {name} » cessera de fonctionner dès le prochain déploiement : il faudra saisir le nouveau sur l'équipement.",
  "radius.secret_title": "Secret partagé",
  "radius.secret_desc": "Saisissez ce secret sur l'équipement « {name} », puis déployez le service pour qu'il soit pris en compte.",
  "radius.secret_once": "Copiez-le maintenant : il ne sera plus jamais affiché.",
  "err.radius_too_many": "Nombre maximal de clients RADIUS atteint.",
  "err.radius_not_running": "Le service RADIUS n'est pas démarré sur ce nœud : déployez-le d'abord.",
  "radius.tab_directory": "Annuaire",
  "radius.dir.intro": "Le service RADIUS interroge votre Active Directory en LDAPS, en lecture seule, avec un compte de service : état du compte (activé, verrouillé, expiré) et appartenance aux groupes, y compris imbriqués. Aucun mot de passe d'utilisateur ne transite : l'authentification des appareils se fait par certificat (EAP-TLS). Les règles d'accès qui s'appuient sur ces informations viennent aux étapes suivantes.",
  "radius.dir.conn_title": "Connexion à l'annuaire",
  "radius.dir.read_only": "Lecture seule",
  "radius.dir.urls": "Contrôleurs de domaine (LDAPS)",
  "radius.dir.urls_help": "Un par ligne, 5 au plus, tous en ldaps:// (le LDAP en clair est refusé). Le premier qui répond est utilisé.",
  "radius.dir.base_dn": "DN de base",
  "radius.dir.base_dn_help": "Racine de la recherche, en général celle du domaine.",
  "radius.dir.bind_dn": "Compte de service",
  "radius.dir.bind_dn_help": "Nom UPN ou DN d'un compte standard sans aucun droit particulier (droits de lecture seuls).",
  "radius.dir.bind_pw": "Mot de passe du compte de service",
  "radius.dir.pw_set": "Un mot de passe est enregistré (chiffré). Laissez vide pour le conserver.",
  "radius.dir.pw_none": "Aucun mot de passe enregistré.",
  "radius.dir.pw_clear": "Effacer le mot de passe enregistré",
  "radius.dir.tls_verify": "Vérifier le certificat du contrôleur de domaine",
  "radius.dir.tls_off_title": "Vérification désactivée",
  "radius.dir.tls_off_body": "Le mot de passe du compte de service pourrait être présenté à un faux serveur. Réservez ce réglage à un essai ; préférez fournir l'autorité de certification ci-contre.",
  "radius.dir.ca": "Autorité de certification (PEM)",
  "radius.dir.ca_help": "Certificat de l'AC qui a signé ceux des contrôleurs de domaine, si elle n'est pas déjà reconnue par ce serveur.",
  "radius.dir.lockout_note": "Attention : un mot de passe faux compte dans la politique de verrouillage du domaine. Après quelques essais, le compte de service est bloqué et tout le service d'accès avec lui. Corrigez le mot de passe avant de relancer le test.",
  "radius.dir.test": "Enregistrer et tester la liaison",
  "radius.dir.test_ok": "Liaison réussie : l'annuaire est joignable avec ce compte.",
