  "radius.eap_on": "activé",
  "radius.eap_off": "non déployé",
  "radius.pki.intro": "EAP-TLS authentifie les clients par certificat (pas de mot de passe). Il faut : les autorités de certification de confiance (celles qui émettent les certificats des postes et des utilisateurs), un certificat pour ce serveur RADIUS, et la révocation (CRL) pour refuser un certificat retiré. Tout est contrôlé ici, puis revérifié par le service au déploiement.",
  "radius.pki.ready_title": "État de la configuration EAP-TLS",
  "radius.pki.ready": "Prêt à déployer",
  "radius.pki.empty": "Non configuré : EAP-TLS désactivé",
