  "radius.pki.p.server_chain": "Le certificat du serveur n'est pas relié à une racine de la liste : ajoutez son autorité émettrice et sa racine.",
  "radius.pki.p.crl_missing": "« {name} » : aucune CRL. Indiquez son adresse ou envoyez le fichier.",
