  "radius.pki.ca_title": "Autorités de certification de confiance",
  "radius.pki.ca_desc": "Racine et intermédiaires de votre PKI, dans l'ordre que vous voulez. Un client dont le certificat ne se rattache pas à cette liste est refusé.",
  "radius.pki.ca_add": "Ajouter une autorité",
