  "radius.journal.intro": "Authentifications reçues par ce nœud : le poste, l'équipement qui l'a relayé, le certificat présenté, la règle qui a décidé et la raison d'un refus. Un paquet d'un équipement non déclaré et une alerte TLS du poste apparaissent en « diagnostic ». Cliquez sur une ligne pour le détail et ce qu'il faut vérifier.",
