  "radius.mfa.tls_off": "Le mot de passe et le code circulent vers un serveur dont l'identité n'est pas contrôlée. À réserver aux essais.",
  "radius.mfa.ca": "Autorité de certification du fournisseur (PEM, facultatif)",
  "radius.mfa.ca_help": "À fournir si le fournisseur utilise une autorité interne. Ne collez que des certificats.",
  "radius.mfa.otp_note": "Le code d'un même couple ne peut en général servir qu'une fois : un second essai avec le même code est refusé par le fournisseur. Le fournisseur doit accepter l'échange « mot de passe » pour le client déclaré ci-dessus.",
  "radius.mfa.redeploy": "Les changements ne sont pris en compte qu'au prochain déploiement du service (onglet Service).",
