  "radius.mfa.probe_server_error": "Le fournisseur répond par une erreur serveur (HTTP {status}) : vérifiez son état.",
  "radius.mfa.probe_tls": "Certificat du fournisseur refusé : fournissez son autorité de certification.",
  "radius.mfa.probe_timeout": "Le fournisseur n'a pas répondu dans le délai.",
  "radius.mfa.probe_unreachable": "Fournisseur injoignable (nom, pare-feu, port).",
  "radius.mfa.probe_not_configured": "Renseignez l'adresse du point de jeton et l'identifiant du client, enregistrez, puis testez.",
  "radius.nps.intro": "Reprenez la configuration d'un NPS Windows existant : ses clients RADIUS deviennent des clients DDI-Buntu et ses stratégies réseau deviennent des règles d'accès. La console analyse le fichier et vous montre, pour chaque élément, s'il est repris, adapté ou non pris en charge, avec la raison. Rien n'est écrit avant votre validation, et rien n'est déployé : clients et règles attendent « Déployer ».",
  "radius.nps.s1_title": "1. Exporter la configuration du NPS",
  "radius.nps.s1_body": "Exécutez ce script en administrateur sur le serveur NPS (lecture seule), puis récupérez le fichier XML produit.",
  "radius.nps.copy": "Copier le script",
  "radius.nps.download": "Télécharger (.ps1)",
  "radius.nps.secrets_title": "Le fichier contient les secrets partagés en clair",
  "radius.nps.secrets_body": "C'est une exigence de netsh (exportPSK=YES) : le fichier permet de reprendre les secrets des équipements sans les ressaisir. Transmettez-le avec précaution et supprimez-le dès l'import terminé. La console ne conserve pas le fichier et ne réaffiche jamais ces secrets.",
  "radius.nps.s2_title": "2. Déposer le fichier et analyser",
  "radius.nps.file": "Fichier d'export NPS (.xml)",
  "radius.nps.file_help": "Taille maximale : 8 Mo. Les fichiers UTF-16 produits par netsh sont reconnus.",
  "radius.nps.too_big": "Fichier trop volumineux (8 Mo au plus).",
  "radius.nps.analyse": "Analyser",
  "radius.nps.analysing": "Analyse en cours…",
  "radius.nps.dir_title": "Les groupes n'ont pas pu être résolus",
  "radius.nps.dir_missing": "Les stratégies désignent leurs groupes par SID : il faut l'annuaire pour les retrouver. Renseignez l'onglet « Annuaire », puis analysez de nouveau le fichier. Les règles à groupes ne sont pas reprises en attendant.",
  "radius.nps.dir_unreachable": "L'annuaire n'a pas répondu (liaison, certificat ou réseau) : voir l'onglet « Annuaire ». Corrigez-le puis analysez de nouveau le fichier. Les règles à groupes ne sont pas reprises en attendant.",
  "radius.nps.no_clients_container": "Aucun conteneur de clients RADIUS trouvé dans ce fichier : seules les stratégies sont lues.",
  "radius.nps.clients_title": "Clients RADIUS",
