  "radius.nps.conn_title": "{n} stratégie(s) de demande de connexion non reprise(s)",
  "radius.nps.conn_body": "DDI-Buntu authentifie lui-même (EAP-TLS) : il n'a ni relais vers un autre serveur RADIUS ni règle de demande de connexion. Si le NPS relayait des demandes, il faut les prévoir ailleurs.",
  "radius.nps.original": "Conditions d'origine",
