  "pki.nets_hint": "Un réseau par ligne (CIDR). Seuls ces réseaux atteignent le port de la PKI (listes de révocation, inscription).",
  "pki.install_title": "Installer la PKI",
  "pki.install_body": "Installer EJBCA Community avec le nom public « {host} » ? Ce nom ne pourra plus changer. L'image du conteneur (plus d'un gigaoctet) est téléchargée sur docker.io ; l'opération peut durer plusieurs minutes.",
