  "pki.cl.unreachable_body": "Ce nœud ne peut pas lire l'état du cluster : la PKI est laissée telle quelle (ni démarrée ni arrêtée) jusqu'au retour d'etcd.",
  "pki.cl.mark_title": "Mise à jour de la PKI en cours sur « {node} »",
  "pki.cl.mark_body": "EJBCA {from} → {to}, démarrée le {at}. Si le nœud tombait en pleine opération, aucun autre nœud ne démarrerait la PKI sur une base peut-être à moitié migrée.",
