  "pki.cl.vip_hint": "Le nom public de la PKI doit pointer vers l'adresse virtuelle du cluster ({vip}), pas vers un nœud : c'est elle qui suit le leader. Un nom enregistré sur l'adresse d'un seul nœud cesserait de répondre à la bascule.",
  "pki.cl.limits": "Limites : la sauvegarde de retour arrière d'une mise à jour reste sur le nœud qui l'a faite (la validation et le retour arrière se font depuis lui) ; la base d'EJBCA est celle du cluster (sauvegardée et répliquée avec les autres).",
  "pki.danger": "Désinstaller",
  "pki.uninstall": "Désinstaller la PKI",
  "pki.uninstall_body": "Retire le conteneur et son unité. La base, le volume et les secrets sont conservés : les clés des autorités ne sont pas détruites, et une réinstallation retrouve la PKI à l'identique (même nom public obligatoire).",
