  "pki.secrets_missing_body": "L'installation est refusée : de nouveaux secrets rendraient illisibles les clés des autorités déjà dans la base. Restaurez les secrets depuis une sauvegarde ; s'il n'existe aucune autorité avec clé, vous pouvez remettre la PKI à zéro (carte « Remise à zéro »).",
  "pki.data_found_title": "Une PKI existante a été retrouvée (nom public « {host} »)",
