  "pki.reset_title": "Remise à zéro",
  "pki.reset_body": "Efface la base d'EJBCA, son volume et ses secrets, pour repartir d'une PKI neuve (par exemple pour choisir un autre nom public après un essai). Possible uniquement si AUCUNE autorité ne porte de clé : le DDI ne détruit jamais de clé.",
  "pki.reset_refused": "Remise à zéro refusée : {n} autorité(s) avec clé existent (ou la base n'est pas lisible).",
