  "pki.ca.intro": "Autorités de la PKI du DDI. Le plus sûr : une racine HORS LIGNE (sa clé ne touche jamais ce serveur) qui signe une ou plusieurs émettrices en ligne. Le DDI peut aussi créer lui-même la racine (sa clé est alors conservée dans sa base) : c'est le choix le plus simple, courant dans un domaine Active Directory.",
