  "pki.ca.p12_warn": "La clé de cette autorité sera conservée dans la base du DDI : elle ne sera plus « hors ligne ». À réserver à une autorité que vous acceptez d'exposer ainsi (laboratoire, autorité remplaçable, migration vers cette PKI). Le fichier et son mot de passe ne sont gardés nulle part par la console : le DDI les efface dès qu'il les a lus.",
