  "err.pki_update_not_healthy": "La PKI doit être en service (santé EJBCA correcte) pour être mise à jour.",
  "err.pki_update_none": "Aucune mise à jour ne permet cette action.",
  "pki.upd.intro": "EJBCA Community est une image de conteneur : l'appliance cherche chaque jour les nouvelles versions sur Docker Hub. La mise à jour sauvegarde d'abord la base et les fichiers de la PKI, démarre la nouvelle image (elle migre la base d'EJBCA), puis contrôle la santé, le schéma, les autorités, la signature et les CRL. Si un contrôle échoue, tout est remis comme avant sans intervention ; sinon vous validez, et le retour arrière reste possible jusque-là.",
  "pki.upd.not_installed": "La PKI n'est pas installée : rien à mettre à jour.",
  "pki.upd.running_title": "Mise à jour vers EJBCA {to} en cours",
  "pki.upd.running_hint": "La PKI est arrêtée puis relancée : quelques minutes, jusqu'à vingt si la base est volumineuse. La mise à jour continue même si vous fermez cet écran ; les autres actions de la PKI sont suspendues pendant ce temps.",
  "pki.upd.no_key_title": "Aucune clé de récupération",
  "pki.upd.no_key_body": "Le point de retour de la mise à jour reste sur cette machine (14 jours). Sans clé de récupération, une panne de la machine elle-même rendrait les sauvegardes de la PKI illisibles : créez-la dans l'onglet Sauvegarde.",
