  "pki.upd.apply_body": "La PKI sera arrêtée quelques minutes : les certificats déjà émis restent valables, mais l'émission, la révocation et les CRL à la demande sont interrompues. Un point de retour (base et fichiers) est créé avant tout changement ; si un contrôle échoue, EJBCA {from} est remis en service sans intervention. Lisez les notes de mise à niveau de la version avant de continuer.",
