  "pki.rec.intro": "Les clés des autorités sont dans la base de la PKI, sauvegardée avec le reste de l'appliance, mais elles ne se lisent qu'avec les secrets d'EJBCA. Chaque sauvegarde contient donc un lot de ces secrets, chiffré pour une clé de récupération : seul le détenteur de la clé privée peut le rouvrir. L'appliance ne conserve que le certificat public.",
  "pki.rec.state.ok": "Les secrets de la PKI sont dans la dernière sauvegarde",
