  "pki.rec.warn_title": "La clé privée ne sera montrée qu'une seule fois",
  "pki.rec.warn_body": "Elle n'est stockée nulle part, ni sur l'appliance ni dans la console. Conservez-la hors de cette machine (coffre de mots de passe, support hors ligne) : si elle est perdue, les secrets sauvegardés sont définitivement irrécupérables et la PKI ne pourra pas être restaurée.",
  "pki.rec.pass": "Phrase secrète du fichier de clé (conseillée)",
