  "pki.rec.replace_body": "Les sauvegardes déjà faites restent chiffrées pour l'ANCIENNE clé : conservez-la tant qu'elles existent. Les prochaines le seront pour la nouvelle.",
  "pki.rec.offline": "Vous préférez fabriquer la clé ailleurs (coffre matériel, PKI interne) ? Enregistrez seulement son certificat avec : ddibuntu-pki recovery-set CERTIFICAT.pem (RSA 3072 bits minimum).",
  "pki.rec.restore_title": "Restaurer la PKI après un sinistre",
