  "pki.rec.restore_hint": "Avant d'écraser quoi que ce soit : ddibuntu-backup pki-verify --id <ID> --key <clé> contrôle le lot sans rien installer.",
  "pki.rec.key_once_title": "Clé privée de récupération",
