  "pki.rec.key_once_plain": "Le fichier n'est protégé par aucune phrase secrète : quiconque le lit pourra ouvrir les secrets de vos sauvegardes.",
  "pki.rec.key_download": "Télécharger le fichier",
  "pki.rec.key_saved": "J'ai conservé cette clé hors de cette machine",
  "pki.ad.intro": "Chaque autorité de la PKI du DDI (racine, racine hors ligne, émettrice) est publiée automatiquement dans l'Active Directory : les machines du domaine lui font alors confiance. Les racines et les racines hors ligne vont dans « Certification Authorities », les émettrices dans « AIA » (partition Configuration de la forêt). Un compte de service dédié écrit, avec une délégation minimale sur ces deux conteneurs.",
  "pki.ad.warn_title": "Publier une autorité a un effet sur tout le domaine",
  "pki.ad.warn_body": "Une racine publiée dans l'annuaire est approuvée par toutes les machines du domaine (à l'actualisation de la stratégie de groupe, avec l'inscription automatique des certificats activée). Si la clé de la racine est dans la base du DDI, protégez les accès à cette base et aux secrets de l'instance. Un retrait n'est jamais automatique : il se fait autorité par autorité, après confirmation.",
  "pki.ad.pub_title": "Publication",
