  "pki.ad.enable_confirm_body": "Toutes les autorités de la PKI du DDI, actuelles et futures, seront écrites dans l'annuaire et donc approuvées par les machines du domaine. Vous pourrez retirer une autorité à tout moment, une par une.",
  "pki.ad.repair": "Si l'annuaire ne contient plus ce que le DDI y a publié",
