  "pki.cert.p12_key_body": "Elle n'existe que le temps de la requête : ni la PKI ni le serveur ne la stockent, et elle n'apparaît dans aucun journal. Le fichier téléchargé est la seule copie ; si vous le perdez, émettez un nouveau certificat.",
  "pki.cert.radius_hint_title": "Pour le RADIUS de ce DDI, passez par l'onglet RADIUS",
