  "pki.tab_scep": "SCEP",
  "pki.tab_enroll": "Postes",
  "enroll.intro": "Les postes du domaine obtiennent seuls leur certificat EAP-TLS auprès de la PKI du DDI. Le poste fabrique sa clé (elle ne le quitte jamais) et s'authentifie en Kerberos avec son compte d'ordinateur ; le nom du certificat vient de l'annuaire, jamais de la demande. Le renouvellement est automatique.",
  "enroll.step_keytab": "1. Clé du service (keytab)",
  "enroll.keytab_help": "Créez dans l'AD un compte de service dédié portant le nom de service HTTP/<nom de la console>. Cochez « Ce compte prend en charge le chiffrement Kerberos AES 128 / 256 bits » PUIS renouvelez son mot de passe (sans quoi le keytab n'aura que du RC4, refusé ici), exportez son keytab et déposez-le ici. Il est chiffré en base et jamais renvoyé.",
  "enroll.cmd_title": "Commandes pour créer le compte de service et exporter le keytab",
  "enroll.cmd_note": "À lancer par un administrateur du domaine. Les valeurs reprennent le nom de la console saisi plus bas ({host}) et le domaine déduit du groupe ({realm}) : vérifiez-les avant de copier. Le mot de passe du compte n'a pas à être conservé.",
  "enroll.cmd_win": "Active Directory Windows (PowerShell, sur un contrôleur de domaine)",
  "enroll.cmd_samba": "Samba AD (sur un contrôleur de domaine)",
  "enroll.cmd_c_create": "Compte de service dédié (aucun droit particulier)",
  "enroll.cmd_c_aes": "Chiffrement AES, AVANT l'export (sinon le keytab n'aurait que du RC4, refusé ici)",
  "enroll.cmd_c_aes_samba": "Chiffrement AES (attribut 24), puis nouveau mot de passe : sinon le keytab n'aurait que du RC4",
  "enroll.cmd_c_spn": "Nom de service ; setspn -S refuse un nom déjà pris par un autre compte",
  "enroll.cmd_c_export_win": "Export : +rndpass remplace le mot de passe par un mot de passe aléatoire et génère les clés AES ; -setupn laisse le nom de connexion du compte inchangé",
  "enroll.cmd_c_export_samba": "Export du keytab",
  "enroll.cmd_c_check": "Contrôle : doit lister aes256-cts-hmac-sha1-96, sans arcfour-hmac seul",
  "enroll.keytab_none": "Aucun keytab déposé.",
  "enroll.keytab_upload": "Déposer le keytab",
  "enroll.keytab_replace": "Remplacer le keytab",
  "enroll.keytab_saved": "Keytab enregistré",
  "enroll.keytab_remove_title": "Retirer le keytab ?",
  "enroll.keytab_remove_body": "L'enrôlement des postes est désactivé : aucun certificat ne sera plus émis tant qu'un keytab n'est pas déposé.",
  "enroll.step_settings": "2. Réglages",
  "enroll.host": "Nom de la console vu des postes",
  "enroll.host_help": "Doit correspondre au nom de service HTTP/… du keytab.",
  "enroll.ca": "Autorité émettrice",
  "enroll.ca_help": "Elle signe les certificats de postes (profil « machine »).",
  "enroll.ca_pick": "Choisir une autorité",
  "enroll.group": "Groupe autorisé (DN complet)",
  "enroll.group_help": "Seuls les ordinateurs membres de ce groupe (directement ou par un groupe imbriqué) obtiennent un certificat. Gardez-le restreint.",
  "enroll.min_interval": "Délai minimal entre deux émissions d'un poste (secondes)",
  "enroll.min_interval_help": "Protège contre une boucle de demandes.",
  "enroll.per_day": "Émissions maximales par poste et par jour",
  "enroll.per_minute": "Émissions maximales par minute (tous postes)",
  "enroll.per_minute_help": "Les émissions se font l'une après l'autre ; une vague de démarrages est étalée par le script.",
  "enroll.enable": "Enrôlement des postes activé",
  "enroll.incomplete": "Déposez le keytab et renseignez le nom de la console, l'autorité et le groupe pour pouvoir l'activer.",
  "enroll.disable_title": "Désactiver l'enrôlement ?",
  "enroll.disable_body": "Les postes ne pourront plus obtenir ni renouveler leur certificat. Les certificats déjà émis restent valables.",
  "enroll.step_script": "3. Script à déployer",
  "enroll.script_help": "Déployez ce script par GPO (script de démarrage de l'ordinateur) avec l'option -Install : il crée la tâche planifiée qui s'exécute en SYSTEM, vérifie le certificat chaque jour et le renouvelle 30 jours avant l'échéance. Poussez aussi par GPO la chaîne de la PKI dans les autorités racines de confiance.",
  "enroll.deploy_title": "Instructions de déploiement par GPO",
  "enroll.deploy_auto_title": "Repli : script PowerShell à lancer sur un contrôleur de domaine",
  "enroll.deploy_auto_help": "Fait la même chose que le bouton ci-dessus, mais lancé par un administrateur sur un contrôleur de domaine (ou un poste muni des outils RSAT) : à utiliser si la console ne peut pas joindre le domaine. Il peut être relancé sans danger ; commencez par -WhatIf.",
  "enroll.deploy_ou": "Unité d'organisation des postes pilotes (nom distinctif)",
  "enroll.deploy_gpo_download": "Télécharger deploy-gpo.ps1",
  "enroll.deploy_cmd_gpo": "Sur le contrôleur de domaine (PowerShell en administrateur)",
  "enroll.deploy_c_whatif": "Simulation : montre ce qui serait fait, sans rien modifier",
  "enroll.deploy_c_apply": "Mise en place",
  "enroll.deploy_manual": "Pas à pas manuel (sans le script)",
  "enroll.gpo_title": "Depuis la console (recommandé)",
  "enroll.gpo_help": "La console crée la GPO « DDI-Buntu enrolement » dans l'annuaire, dépose ses fichiers dans SYSVOL et la lie à l'unité d'organisation. Elle a besoin d'un compte pour cette seule opération (administrateur du domaine, ou compte autorisé à créer des GPO et à les lier à l'unité) : le mot de passe n'est ni stocké, ni journalisé, ni renvoyé. La liaison passe par LDAPS (serveurs et certificat de l'onglet Annuaire de RADIUS) et par SMB signé vers le contrôleur de domaine. Commencez par « Simuler ».",
  "enroll.gpo_account": "Compte (nom d'utilisateur principal ou DOMAINE\\compte)",
  "enroll.gpo_password": "Mot de passe (utilisé une fois, jamais conservé)",
  "enroll.gpo_check": "Simuler",
  "enroll.gpo_apply": "Mettre en place la GPO",
  "enroll.gpo_confirm_title": "Mettre en place la GPO ?",
  "enroll.gpo_confirm_body": "La GPO « DDI-Buntu enrolement » sera créée (ou mise à jour) et liée à {ou}. Au prochain démarrage, les postes de cette unité exécuteront le script d'enrôlement en SYSTEM : commencez par une unité de postes pilotes.",
  "enroll.gpo_dry_done": "Simulation réussie : rien n'a été modifié.",
  "enroll.gpo_done": "GPO en place ({id}). Redémarrez un poste pilote de l'unité (gpupdate /force puis redémarrage), puis contrôlez-le avec les commandes ci-dessous.",
  "enroll.gpo_step_bind": "Compte",
  "enroll.gpo_step_ou": "Unité d'organisation",
  "enroll.gpo_step_gpo": "GPO dans l'annuaire",
