  "enroll.gpo_did_keep": "déjà en place",
  "enroll.gpo_ou_create": "Créer cette unité d'organisation",
  "enroll.gpo_ou_create_default": "Créer l'unité « Postes-pilotes »",
  "enroll.gpo_ou_confirm_title": "Créer l'unité d'organisation ?",
  "enroll.gpo_ou_confirm_body": "L'unité {ou} sera créée dans l'annuaire avec le compte saisi (rien d'autre n'est modifié). Déplacez ensuite les postes pilotes dedans.",
  "enroll.gpo_ou_created": "Unité {ou} créée. Déplacez-y les postes pilotes (Utilisateurs et ordinateurs Active Directory), ressaisissez le mot de passe, puis lancez « Simuler ».",
  "enroll.gpo_ou_exists": "L'unité {ou} existe déjà. Ressaisissez le mot de passe, puis lancez « Simuler ».",
  "enroll.gpo_mode": "Cible de la GPO",
  "enroll.gpo_mode_ou": "Une unité d'organisation (recommandé)",
  "enroll.gpo_mode_group": "Un groupe d'ordinateurs",
  "enroll.gpo_group_label": "Groupe d'ordinateurs (nom distinctif)",
  "enroll.gpo_group_help": "Par défaut, le groupe autorisé à l'étape 2. La GPO est liée à la racine du domaine mais seuls les ordinateurs membres du groupe l'appliquent ; un poste ajouté au groupe doit redémarrer.",
  "enroll.gpo_confirm_group": "La GPO « DDI-Buntu enrolement » sera créée (ou mise à jour), liée à la racine du domaine et réservée aux ordinateurs du groupe {group} : « Utilisateurs authentifiés » perd le droit de l'appliquer. Au prochain démarrage, ces postes exécuteront le script d'enrôlement en SYSTEM.",
  "enroll.gpo_members": "{n} ordinateur(s) dans le groupe : {names}.",
  "enroll.gpo_members_none": "Le groupe ne contient aucun ordinateur pour l'instant : ajoutez-y les postes pilotes (ils devront redémarrer).",
  "enroll.gpo_step_group": "Groupe",
  "enroll.gpo_step_filter": "Filtrage de sécurité (le groupe seul applique la GPO)",
  "enroll.gpo_group_create": "Créer ce groupe",
  "enroll.gpo_group_confirm_title": "Créer le groupe d'ordinateurs ?",
  "enroll.gpo_group_confirm_body": "Le groupe {ou} sera créé (groupe de sécurité global, vide) avec le compte saisi ; rien d'autre n'est modifié.",
  "enroll.gpo_group_created": "Groupe {ou} créé, vide. Ajoutez-y les postes pilotes (Utilisateurs et ordinateurs Active Directory), ressaisissez le mot de passe, puis lancez « Simuler ».",
  "enroll.gpo_group_exists": "Le groupe {ou} existe déjà. Ressaisissez le mot de passe, puis lancez « Simuler ».",
  "tls.title": "Certificat HTTPS de la console",
  "tls.help": "Le leader fait émettre ce certificat par la PKI du DDI avec tous les noms sous lesquels la console est jointe (nom virtuel du cluster, nœuds, adresses), le renouvelle seul avant l'échéance, et chaque nœud le sert. Plus de certificat auto-signé différent par nœud : les postes n'ont qu'à faire confiance à la racine de la PKI.",
  "tls.auto": "Certificat automatique",
  "tls.ca": "Autorité émettrice",
  "tls.names": "Noms supplémentaires (un par ligne)",
  "tls.names_help": "Le nom virtuel du cluster, par exemple. Les nœuds, leurs adresses et le nom de la console vue des postes sont ajoutés tout seuls ; 8 noms et 4 adresses au plus.",
  "tls.saved": "Réglages enregistrés.",
