  "tls.from_pki": "émis par une autorité",
  "tls.pending": "La base porte un autre certificat que celui que ce nœud sert : il le servira après sa relance (une minute environ).",
  "tls.last_fail": "Dernière tentative en échec : {msg}",
  "tls.not_leader": "Ce nœud est un secondaire : l'émission se fait sur le leader, ce nœud installe le certificat reçu.",
  "tls.truncated": "Plus de noms ou d'adresses que le profil n'en permet : seuls les premiers sont couverts.",
  "tls.no_issuer": "Aucune autorité émettrice active : installez d'abord la PKI du DDI.",
  "err.console_tls_ca_required": "Choisissez l'autorité émettrice pour activer le certificat automatique.",
  "err.console_tls_not_leader": "L'émission se fait sur le leader du cluster.",
  "err.console_tls_disabled": "Activez d'abord le certificat automatique et choisissez l'autorité.",
  "err.console_tls_issue_failed": "La PKI n'a pas pu émettre le certificat : l'ancien reste en place.",
  "enroll.trust_title": "Confiance des postes envers la console",
  "enroll.trust_help": "La console se connecte à son nom, tel que les postes le voient, et vérifie que le certificat présenté couvre ce nom et qu'une autorité installée par la GPO le valide. Sans cela Windows refuse la connexion et rien n'arrive jamais à la console.",
  "enroll.trust_check": "Vérifier",
  "enroll.trust_ok": "Les postes feront confiance à la console : le certificat présenté sous {host} couvre ce nom et est validé par une autorité que la GPO installe.",
  "enroll.trust_unreachable": "La console n'a pas pu se joindre elle-même sous {host} (nom, port 443 ou pare-feu) : vérification impossible d'ici.",
  "enroll.trust_name": "Le certificat présenté sous {host} ne contient pas ce nom (il contient : {names}). Les postes le refuseront.",
  "enroll.trust_untrusted": "Aucune autorité de la GPO ne valide le certificat présenté sous {host}. Activez le certificat HTTPS automatique (Système) ou relancez « Appliquer » depuis la console qui sert ce nom.",
  "enroll.trust_expired": "Le certificat présenté par la console est expiré.",
  "enroll.deploy_s0": "Avant tout : activez l'enrôlement (étape 2) — éteint, la console répond comme si la route n'existait pas — et commencez par un poste pilote.",
  "enroll.deploy_s1": "Les postes doivent faire confiance au certificat HTTPS de la console (auto-signé par défaut). Dans la GPO : Configuration ordinateur › Stratégies › Paramètres Windows › Paramètres de sécurité › Stratégies de clé publique › Autorités de certification racines de confiance › Importer. Importez le certificat de la console (commande ci-dessous) ; s'il est déjà signé par une autorité approuvée des postes, il n'y a rien à faire.",
  "enroll.deploy_s2": "Importez dans le même magasin la racine de la PKI du DDI (onglet Autorités › télécharger la chaîne) : les postes en ont besoin pour valider le certificat du serveur RADIUS en EAP-TLS.",
  "enroll.deploy_s3": "Copiez enroll.ps1 dans le dossier des scripts de démarrage de la GPO : Configuration ordinateur › Stratégies › Paramètres Windows › Scripts (démarrage/arrêt) › Démarrage › Afficher les fichiers (dossier \\\\{domain}\\SYSVOL\\{domain}\\Policies\\{GUID}\\Machine\\Scripts\\Startup).",
  "enroll.deploy_s4": "Onglet « Scripts » (et non « Scripts PowerShell ») › Ajouter : nom du script « powershell.exe », paramètres « -NoProfile -ExecutionPolicy Bypass -File \"\\\\{domain}\\SYSVOL\\{domain}\\Policies\\{GUID}\\Machine\\Scripts\\Startup\\enroll.ps1\" -Install ».",
  "enroll.deploy_s5": "Liez la GPO à l'unité d'organisation des postes pilotes. Ces postes doivent aussi être membres du groupe autorisé (étape 2).",
  "enroll.deploy_s6": "Au démarrage suivant, le script crée la tâche « DDI-Buntu enrolement » (compte SYSTEM) et la lance aussitôt ; elle se relance à chaque démarrage et chaque jour à 03:30, et renouvelle le certificat 30 jours avant l'échéance. Le certificat apparaît dans l'onglet Certificats (profil « machine ») et dans Activité ci-dessous.",
  "enroll.deploy_s7": "Vérifiez sur le poste pilote (commandes ci-dessous). Un refus s'explique dans le journal du poste (%ProgramFiles%\\DDI-Buntu\\enroll.log) et dans Activité.",
  "enroll.deploy_cmd_trust": "Sur la console (ligne de commande) : exporter son certificat HTTPS",
  "enroll.deploy_cmd_pilot": "Sur un poste pilote (invite administrateur) : essai à la main et contrôles",
