  "pki.scep.intro": "SCEP permet à un équipement (commutateur, borne Wi-Fi, pare-feu, poste géré) de demander lui-même son certificat à la PKI, avec sa propre clé. EJBCA Community n'accepte que le mode « autorité » : chaque équipement est d'abord préenregistré ici (nom, profil, noms alternatifs) et reçoit un défi à usage unique, qu'il présente une fois pour s'inscrire.",
  "pki.scep.alias_title": "Alias SCEP",
  "pki.scep.enabled": "Activé",
  "pki.scep.disabled": "Désactivé",
