  "pki.scep.disable": "Désactiver SCEP",
  "pki.scep.enable_done": "SCEP activé",
  "pki.scep.disable_done": "SCEP désactivé",
  "pki.scep.disable_title": "Désactiver SCEP ?",
  "pki.scep.disable_body": "Les équipements ne pourront plus s'inscrire. Les équipements préenregistrés et les certificats déjà émis sont conservés.",
  "pki.scep.disabled_hint": "Activez SCEP pour préenregistrer des équipements.",
  "pki.scep.url": "Adresse SCEP à donner aux équipements",
  "pki.scep.url_help": "HTTP, port {port} (déjà ouvert aux réseaux autorisés de la PKI). Le défi voyage dans la demande, chiffrée pour l'autorité : il ne circule jamais en clair.",
  "pki.scep.limits": "Limites d'EJBCA Community : pas de défi partagé (donc ni inscription de masse par un MDM, ni Intune) ; un défi par équipement, à usage unique. Un renouvellement passe par un nouveau défi.",
  "pki.scep.no_rsa": "Aucune autorité émettrice en RSA. SCEP chiffre la demande de l'équipement pour la clé de l'autorité : elle doit être en RSA. Créez une émettrice RSA dans l'onglet Autorités.",
  "pki.scep.ca_title": "Autorité à faire connaître aux équipements",
  "pki.scep.ca_help": "L'équipement doit connaître l'autorité avant de s'inscrire : téléchargez son certificat, ou comparez l'empreinte SHA-256 ci-dessous avec celle que l'équipement affiche.",
  "pki.scep.offer": "Préenregistrer un équipement",
  "pki.scep.offer_desc": "L'équipement recevra un défi à usage unique. Son nom et ses noms alternatifs viennent de ce formulaire, jamais de sa demande de certificat.",
